// bundledNamedFaces materializes the generated tables as catalog faces.
func bundledNamedFaces() []NamedFace {
	faces := make([]NamedFace, 0, len(bundledFaces))
	for _, f := range bundledFaces {
		face := NewMetricsFace(f.units, f.ascent, f.descent, f.lineGap, bundledRunes, f.advances)
		if face == nil {
			continue
		}
		faces = append(faces, NamedFace{Family: f.family, Weight: f.weight, Italic: f.italic, Face: face})
	}
	return faces
}
